// Public browser-only Supabase project settings, supplied by the site owner.
// Never add a service_role key, OAuth client secret, or private key to auth-config.js.
const AUTH_CONFIG = window.GBB_AUTH_CONFIG || {};
const AUTH_READY = Boolean(/^https:\/\/[^/]+$/.test(String(AUTH_CONFIG.supabaseUrl || '').replace(/\/$/, '')) && AUTH_CONFIG.supabasePublishableKey);
let authClientPromise = null;
let authSession = null;
let authMode = 'login';
function authClient() {
  if (!AUTH_READY) return Promise.resolve(null);
  if (!authClientPromise) {
    authClientPromise = import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.118.0/+esm')
      .then(({createClient}) => createClient(AUTH_CONFIG.supabaseUrl, AUTH_CONFIG.supabasePublishableKey, {
        auth: {flowType: 'pkce', persistSession: true, autoRefreshToken: true, detectSessionInUrl: true}
      }))
      .catch(error => {authClientPromise = null; throw error;});
  }
  return authClientPromise;
}
function authSetupNotice() {
  modal('Sign-in setup required', 'Google, Apple and email sign-in need a connected Supabase project. The buttons are ready, but sign-in is not active until the site owner configures the providers. No account was created.');
}
async function startSocialSignIn(provider) {
  if (!AUTH_READY) { authSetupNotice(); return; }
  try {
    const client = await authClient();
    const {error} = await client.auth.signInWithOAuth({
      provider,
      options:{redirectTo: window.location.origin + window.location.pathname + '?auth_callback=1#/login'}
    });
    if (error) throw error;
  } catch(error) { modal('Sign-in could not start', String(error?.message || 'Please check the provider setup.')); }
}
async function submitEmailAuth(form) {
  if (!AUTH_READY) { authSetupNotice(); return; }
  const button = form.querySelector('button[type=submit]');
  if (button) button.disabled = true;
  try {
    const client=await authClient();
    const data=new FormData(form);
    const email=String(data.get('email')||'').trim();
    const password=String(data.get('password')||'');
    let result;
    if (authMode==='signup') {
      result=await client.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin+window.location.pathname+'#/login'}});
    } else {
      result=await client.auth.signInWithPassword({email,password});
    }
    if (result.error) throw result.error;
    if (result.data.session) {authSession=result.data.session;location.hash='#/bookings';}
    else modal('Check your inbox','Confirm your email address using the message from Get By Boat to finish creating your account.');
  } catch(error) { modal(authMode==='signup'?'Registration failed':'Login failed', String(error?.message || 'Please try again.')); }
  finally {if(button)button.disabled=false;}
}
async function initializeAuth() {
  if (!AUTH_READY) return;
  try {
    const client=await authClient();
    const {data,error}=await client.auth.getSession();
    if(error) throw error;
    authSession=data.session;
    if(new URLSearchParams(window.location.search).has('auth_callback')){
      history.replaceState(null,'',window.location.pathname+'#/login');
      if(authSession){location.hash='#/bookings';toast('Welcome to Get By Boat!');}
      else render();
    }
  }catch(error){console.warn('Auth initialization unavailable:',error?.message||error);}
}
