function icon(name,cls=''){return `<svg aria-hidden="true" class="icon ${cls}" viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" fill="none" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.star}</svg>`}
function waveLogo(){return `<span class="logo-mark" aria-hidden="true"><svg viewBox="0 0 48 36" width="36" height="28" fill="none"><path d="M4 18C13 18 16 7 24 7s11 11 20 11" stroke="#00A8C6" stroke-width="5" stroke-linecap="round"/><path d="M4 28c9 0 12-11 20-11s11 11 20 11" stroke="#006C87" stroke-width="5" stroke-linecap="round"/></svg></span>`}
function logo(){return `<a class="logo" href="#/" aria-label="Get By Boat, home">${waveLogo()}<span>Get By Boat</span></a>`}
function header(active=''){const role=window.GBB_ACCOUNT_ROLE;return `<header class="site-head"><div class="nav shell">${logo()}<nav class="nav-links" aria-label="Main navigation"><a href="#/boats" class="${active==='boats'?'active':''}">Boat Rental</a><a href="#/how-it-works">How it works</a></nav><div class="nav-right"><span class="locale">${icon('globe')} EN · EUR</span><a class="text-nav" href="${window.GBB_ACCOUNT_LINK||'#/login'}">${window.GBB_ACCOUNT_LINK?'My account':'Log in'}</a>${role!=='customer'?`<a class="btn btn-small" href="#/owner">${role==='owner'?'My boats':'List your boat'} ${icon('arrow')}</a>`:''}</div><button class="mobile-menu-btn" data-action="menu" aria-label="Open menu" aria-expanded="${state.mobile}">${icon(state.mobile?'close':'menu')}</button></div>${state.mobile?`<nav class="mobile-menu" aria-label="Mobile navigation"><a href="#/boats">Boat Rental</a><a href="#/how-it-works">How it works</a><a href="${window.GBB_ACCOUNT_LINK||'#/login'}">${window.GBB_ACCOUNT_LINK?'My account':'Log in'}</a><a href="${role==='owner'?'#/owner':'#/bookings'}">${role==='owner'?'My boats':'My bookings'}</a>${role!=='customer'?`<a href="#/owner">${role==='owner'?'Manage boats':'List your boat'}</a>`:''}</nav>`:''}</header>`}
function footer(){return `<footer class="footer"><div class="shell footer-columns"><div><div class="footer-logo">${logo()}</div><p>More than a booking. Your next holiday starts here.</p></div><div><h4>Explore</h4><a href="#/boats">Discover boats</a><a href="#/boats?country=Croatia">Croatia</a><a href="#/boats?country=Greece">Greece</a><a href="#/boats?country=Italy">Italy</a></div><div><h4>Get By Boat</h4><a href="#/how-it-works">How it works</a><a href="#/owner">List your boat</a><a href="#/about">About us</a><a href="#/contact">Contact</a><a href="#/faq">FAQ</a></div><div><h4>Say hello to summer</h4><p>Unforgettable destinations. One beautiful horizon.</p><a class="footer-email" href="mailto:pere.juran@gmail.com">pere.juran@gmail.com</a><div class="footer-countries">Croatia · Greece · Spain · Italy · Malta<br>France · USA · Bahamas · Australia</div></div></div><div class="shell footer-bottom"><span>© 2026 Get By Boat. All rights reserved.</span><nav class="footer-legal" aria-label="Legal"><a href="#/privacy">Privacy Policy</a><a href="#/terms">Terms &amp; Conditions</a></nav></div></footer>`}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove('show'),4200)}
function searchWidget(compact=false){return `<form class="search-widget ${compact?'search-widget-compact':''}" id="${compact?'quick-search':'hero-search'}"><div class="search-fields"><label class="search-field search-location"><span>${icon('pin')} Departure location</span><input name="location" type="text" aria-label="Departure location" placeholder="Where would you like to go?" value="${safe(state.filters.location)}" autocomplete="off"></label><label class="search-field"><span>${icon('calendar')} From</span><input type="date" name="start" aria-label="Starting date" value="${safe(state.start)}"></label><label class="search-field"><span>${icon('calendar')} To</span><input type="date" name="end" aria-label="Ending date" value="${safe(state.end)}"></label><label class="search-field"><span>${icon('ship')} Boat type</span><select name="type" aria-label="Boat type"><option value="">Any type</option>${BOAT_TYPES.map(t=>`<option value="${t.value}" ${state.filters.type===t.value?'selected':''}>${t.label}</option>`).join('')}</select></label></div><button class="btn btn-search" type="submit">${icon('search')} Search boats</button></form>`}
function destinationCard(c){return `<a href="#/boats?country=${encodeURIComponent(c.name)}" class="destination-card"><img src="${IMG(c.photo)}" alt="Yachting scenery in ${c.name}" loading="lazy"><div class="destination-shade"></div><div class="destination-copy"><span>${c.subtitle}</span><h3>${c.name}</h3><small>${c.count}</small></div><span class="destination-arr">${icon('arrow')}</span></a>`}
