const demoReservations=[];
function bookingMode(b){return 'request'}
function bookingLabel(b){return 'Request to book'}
function bookingBadge(b){return `<span class="booking-mode-badge">${bookingLabel(b)}</span>`}
function nextBookingStatus(status,action){const transitions={pending_owner:{accept:'awaiting_payment',decline:'declined'},awaiting_payment:{pay:'confirmed'}};return transitions[status]?.[action]||null}
function bookingExplanation(b){return 'The owner must accept your request first. You then pay to confirm your booking. This preview does not send requests or take payments.'}
function demoBookingPanels(ownerView=false){return `<section class="booking-demo-panel"><h2>${ownerView?'Booking requests':'Your booking previews'}</h2><p class="booking-demo-note">Interactive demo only. Nothing is sent or charged. These previews disappear when you refresh.</p>${demoReservations.length?demoReservations.map(r=>{const boat=BOATS.find(b=>b.id===r.boatId);const labels={pending_owner:'Waiting for owner approval',awaiting_payment:'Awaiting payment',declined:'Declined',confirmed:'Confirmed — demo only'};return `<article class="demo-reservation"><h3>${safe(boat.name)}</h3><p>${safe(r.start)} · 09:00 → ${safe(r.end)} · 19:00</p><p>Request to book · ${rentalMoney(r.total)}</p><strong role="status">${labels[r.status]}</strong><div class="demo-actions">${ownerView&&r.status==='pending_owner'?`<button class="btn" data-action="demo-accept" data-id="${r.id}">Accept (demo)</button><button class="outline-button" data-action="demo-decline" data-id="${r.id}">Decline (demo)</button>`:''}${!ownerView&&r.status==='awaiting_payment'?`<button class="btn" data-action="demo-pay" data-id="${r.id}">Simulate successful payment</button>`:''}${!ownerView&&r.status==='pending_owner'?'<a href="#/owner" class="section-link">Try owner approval →</a>':''}</div></article>`}).join(''):'<p>No booking previews yet. Choose a boat and dates to try a flow.</p>'}</section>`}
function ownerBookingModes(){return `<section class="booking-demo-panel"><h2>Booking policy</h2><p>All boats are available upon request. Owners must accept each request before the customer can proceed to payment.</p></section>${demoBookingPanels(true)}`}
